import { gsap } from 'gsap';
import {
  uv,
  add,
  sub,
  mul,
  mix,
  smoothstep,
  vec3,
  color,
  abs
} from 'three/tsl';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    BoxGeometry,
    PlaneGeometry,
    MeshStandardNodeMaterial,
    Color
  } = ctx.THREE;

  const root = new Group();

  // ---------- Utility ----------
  const gradientColors = {
    a: new Color('#101017'),
    b: new Color('#1a1a22')
  };
  const accentColor = new Color('#ff2a38');
  const surfaceColor = new Color('#14141a');

  // ---------- Gradient Material ----------
  function makeCellMaterial() {
    const uvNode = uv(); // vec2
    const t = add(uvNode.x, uvNode.y); // diagonal 0‑1
    const baseGrad = mix(color(gradientColors.a), color(gradientColors.b), t);
    const band = smoothstep(0.325, 0.475, t); // ~0.15 width centered at 0.4
    const bright = add(baseGrad, mul(vec3(1, 1, 1), mul(band, 0.06)));
    const mat = new MeshStandardNodeMaterial();
    mat.color = bright;
    mat.metalness = 0.45;
    mat.roughness = 0.5;
    mat.clearcoat = 0.2;
    mat.transparent = true;
    mat.opacity = 0;
    return mat;
  }

  // ---------- Tick Bar Material ----------
  function makeTickMaterial() {
    const mat = new MeshStandardNodeMaterial();
    mat.emissive = color(accentColor);
    mat.emissiveIntensity = 1.3;
    mat.color = color(accentColor);
    mat.transparent = true;
    mat.opacity = 0;
    return mat;
  }

  // ---------- Create Cell ----------
  const cells = [];

  // Cell definitions
  const cellDefs = [
    {
      // Dominant cell
      width: 3.25,
      height: 3.5,
      depth: 0.06,
      padding: 0.5,
      value: { text: '0.002 mm', opts: { fontSize: 124, color: '#e8ecf2', align: 'center' } },
      label: { text: 'Case tolerance, CNC pass', opts: { fontSize: 18, color: '#e8ecf2', align: 'center' } },
      pos: { x: -1.125, y: 0 }
    },
    {
      // Top secondary
      width: 2.0,
      height: 1.625,
      depth: 0.06,
      padding: 0.5,
      value: { text: '38 h', opts: { fontSize: 68, color: '#e8ecf2', align: 'center' } },
      label: { text: 'Power reserve, NA-01', opts: { fontSize: 18, color: '#e8ecf2', align: 'center' } },
      pos: { x: 1.75, y: 0.9375 }
    },
    {
      // Bottom secondary
      width: 2.0,
      height: 1.625,
      depth: 0.06,
      padding: 0.5,
      value: { text: '214', opts: { fontSize: 68, color: '#e8ecf2', align: 'center' } },
      label: { text: 'Components per calibre', opts: { fontSize: 18, color: '#e8ecf2', align: 'center' } },
      pos: { x: 1.75, y: -0.9375 }
    }
  ];

  const timelines = [];

  for (let i = 0; i < cellDefs.length; i++) {
    const def = cellDefs[i];
    const cellGroup = new Group();

    // Geometry & material
    const geometry = new BoxGeometry(def.width, def.height, def.depth);
    const material = makeCellMaterial();
    const slab = new Mesh(geometry, material);
    slab.castShadow = true;
    slab.receiveShadow = true;
    cellGroup.add(slab);

    // Tick bar (top‑left inside padding)
    const tickGeom = new PlaneGeometry(0.4, 0.05);
    const tickMat = makeTickMaterial();
    const tick = new Mesh(tickGeom, tickMat);
    tick.position.set(
      -def.width / 2 + def.padding + 0.4 / 2,
      def.height / 2 - def.padding - 0.05 / 2,
      def.depth / 2 + 0.001
    );
    cellGroup.add(tick);

    // Value text
    const valueObj = ctx.fontAtlas.createText(def.value.text, {
      fontSize: def.value.opts.fontSize,
      color: def.value.opts.color,
      align: def.value.opts.align,
      letterSpacing: -0.005
    });
    valueObj.position.set(0, 0, def.depth / 2 + 0.002);
    cellGroup.add(valueObj);

    // Label text (below value)
    const labelObj = ctx.fontAtlas.createText(def.label.text, {
      fontSize: def.label.opts.fontSize,
      color: def.label.opts.color,
      align: def.label.opts.align,
      letterSpacing: 0.08
    });
    const labelOffsetY = -def.height / 2 + def.padding + 0.1; // a bit above bottom padding
    labelObj.position.set(0, labelOffsetY, def.depth / 2 + 0.002);
    cellGroup.add(labelObj);

    // Position the whole cell
    cellGroup.position.set(def.pos.x, def.pos.y + 0.2, 0); // start offset for entrance
    // Store original Y for animation
    const targetY = def.pos.y;

    // Fade‑up entrance timeline
    const tl = gsap.timeline({ paused: true });
    tl.to(
      cellGroup.position,
      { y: targetY, duration: 0.5, ease: 'power2.out' }
    );
    // Opacity tween for all materials inside the cell
    const mats = [material, tickMat];
    tl.to(
      mats.map(m => m),
      { opacity: 1, duration: 0.5, ease: 'power2.out' },
      0
    );
    timelines.push(tl);

    // Hover interaction
    const hoverIn = gsap.timeline({ paused: true });
    hoverIn.to(
      cellGroup.scale,
      { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' }
    );

    const hoverOut = gsap.timeline({ paused: true });
    hoverOut
      .to(
        cellGroup.scale,
        { x: 1.04, y: 1.04, z: 1.04, duration: 0.1, ease: 'power2.out' }
      )
      .to(
        cellGroup.scale,
        { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
      );

    cellGroup.userData.handlers = {
      hoverIn: () => hoverIn.play(0),
      hoverOut: () => hoverOut.play(0)
    };
    timelines.push(hoverIn, hoverOut);

    cells.push(cellGroup);
    root.add(cellGroup);
  }

  // ---------- Header Caption ----------
  const headerText = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: '#ff2a38',
    align: 'left',
    letterSpacing: 0.12
  });
  headerText.position.set(-2.75, 2.25, 0);
  root.add(headerText);

  // ---------- Entrance Stagger ----------
  const masterTL = gsap.timeline();
  cells.forEach((c, idx) => {
    const tl = timelines[idx * 3]; // each cell has its entrance timeline first
    masterTL.add(tl, idx * 0.08);
  });
  masterTL.play();

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach(t => {
      try {
        t.kill();
      } catch (_) {}
    });
    // dispose geometries & materials
    root.traverse(obj => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach(m => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  return root;
}
